import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { doc, getDoc, updateDoc, collection, getDocs, query, where, orderBy, limit } from 'firebase/firestore';
import { db } from '../../firebase';
import { useNotification } from './NotificationSystem';
import { 
  FiArrowLeft, FiStar, FiTrendingUp, FiTrendingDown, FiBarChart2, 
  FiCalendar, FiDollarSign, FiCheckCircle, FiClock, FiAlertTriangle,
  FiFileText, FiUser, FiEdit2, FiSave, FiX, FiPlus, FiActivity,
  FiTarget, FiAward, FiRefreshCw
} from 'react-icons/fi';

export default function VendorPerformance() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { showSuccess, showError } = useNotification();
  
  const [vendor, setVendor] = useState(null);
  const [loading, setLoading] = useState(true);
  const [performanceData, setPerformanceData] = useState({});
  const [performanceTrend, setPerformanceTrend] = useState([]);
  const [recentActivity, setRecentActivity] = useState([]);
  const [selectedTimeframe, setSelectedTimeframe] = useState('3months');

  const performanceCategories = [
    { key: 'completion', label: 'Completion Rate', icon: FiCheckCircle },
    { key: 'timeliness', label: 'On-Time Delivery', icon: FiClock },
    { key: 'quality', label: 'Quality Score', icon: FiAward },
    { key: 'efficiency', label: 'Operational Efficiency', icon: FiTrendingUp },
    { key: 'reliability', label: 'Reliability', icon: FiBarChart2 },
    { key: 'volume', label: 'Work Volume', icon: FiActivity }
  ];

  useEffect(() => {
    if (id) {
      fetchVendorPerformance();
    }
  }, [id]);

  const calculateAutoRating = (completionRate, onTimeRate, qualityScore, totalVolume) => {
    // Base rating on completion rate (0-5 scale)
    let rating = (completionRate / 100) * 5;
    
    // Adjust for on-time delivery
    const onTimeBonus = (onTimeRate / 100) * 0.5;
    rating += onTimeBonus;
    
    // Adjust for quality (if available)
    if (qualityScore > 0) {
      const qualityBonus = (qualityScore / 100) * 0.3;
      rating += qualityBonus;
    }
    
    // Volume bonus for vendors with significant work
    if (totalVolume > 10) {
      rating += 0.2;
    }
    
    // Ensure rating is between 0-5
    return Math.max(0, Math.min(5, rating));
  };

  const calculateCategoryRatings = (performanceData) => {
    const {
      completionRate = 0,
      onTimeRate = 0,
      qualityScore = 0,
      totalPOs = 0,
      totalJobs = 0,
      efficiencyScore = 0
    } = performanceData;

    return {
      completion: (completionRate / 100) * 5,
      timeliness: (onTimeRate / 100) * 5,
      quality: (qualityScore / 100) * 5,
      efficiency: (efficiencyScore / 100) * 5,
      reliability: ((completionRate + onTimeRate) / 200) * 5,
      volume: Math.min(5, (totalPOs + totalJobs) / 5) // Cap at 5 stars
    };
  };

  const fetchVendorPerformance = async () => {
    try {
      setLoading(true);
      
      // Fetch vendor details
      const vendorDoc = await getDoc(doc(db, 'vendors', id));
      if (!vendorDoc.exists()) {
        showError('Vendor not found');
        navigate('/admin/vendors');
        return;
      }
      
      const vendorData = { id: vendorDoc.id, ...vendorDoc.data() };
      setVendor(vendorData);

      // Fetch purchase orders
      const posQuery = query(
        collection(db, 'purchaseOrders'), 
        where('vendorId', '==', id)
      );
      const posSnapshot = await getDocs(posQuery);
      const pos = posSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      // Fetch job assignments
      const jobsQuery = query(
        collection(db, 'jobAssignments'), 
        where('vendorId', '==', id)
      );
      const jobsSnapshot = await getDocs(jobsQuery);
      const jobs = jobsSnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      // Calculate performance metrics
      const totalPOs = pos.length;
      const completedPOs = pos.filter(po => po.status === 'completed').length;
      const pendingPOs = pos.filter(po => po.status === 'pending').length;
      const cancelledPOs = pos.filter(po => po.status === 'cancelled').length;
      
      // Calculate on-time delivery
      const onTimePOs = pos.filter(po => {
        if (po.status === 'completed' && po.deliveryDate && po.completedAt) {
          const deliveryDate = po.deliveryDate.toDate ? po.deliveryDate.toDate() : new Date(po.deliveryDate);
          const completedAt = po.completedAt.toDate ? po.completedAt.toDate() : new Date(po.completedAt);
          return completedAt <= deliveryDate;
        }
        return false;
      }).length;

      // Calculate financial metrics
      const totalSpend = pos.reduce((sum, po) => sum + (parseFloat(po.totalAmount) || 0), 0);
      const avgOrderValue = totalPOs > 0 ? totalSpend / totalPOs : 0;

      // Calculate job metrics
      const totalJobs = jobs.length;
      const completedJobs = jobs.filter(job => job.status === 'completed').length;
      const pendingJobs = jobs.filter(job => job.status === 'pending').length;
      const avgJobValue = jobs.length > 0 ? 
        jobs.reduce((sum, job) => sum + (parseFloat(job.budget) || 0), 0) / jobs.length : 0;

      // Calculate operational efficiency from material tracking
      let weightedCompletionSum = 0;
      let weightedDenominator = 0;
      let totalOperations = 0;

      pos.forEach(po => {
        const items = Array.isArray(po.items) ? po.items : [];
        const operationsStatus = po.operationsStatus || {};
        const materialTracking = po.materialTracking || {};

        items.forEach((item, idx) => {
          if (!item || !item.operation) return;
          const operationKey = `${idx}_${item.operation}`;
          const mt = materialTracking[operationKey];
          let completionRate = 0;
          
          if (mt && typeof mt.completionRate === 'number') {
            completionRate = mt.completionRate;
          } else {
            const status = typeof operationsStatus[operationKey] === 'string'
              ? operationsStatus[operationKey]
              : (operationsStatus[idx]?.[item.operation]);
            if (status === 'completed') completionRate = 100;
            else if (status === 'in_progress' || status === 'partial') completionRate = 50;
            else completionRate = 0;
          }
          
          const qty = parseFloat(item.quantity) || 1;
          weightedCompletionSum += completionRate * qty;
          weightedDenominator += qty;
          totalOperations += 1;
        });
      });

      const autoCompletionPercent = weightedDenominator > 0
        ? (weightedCompletionSum / weightedDenominator)
        : (totalPOs > 0 ? (completedPOs / totalPOs) * 100 : 0);

      // Calculate quality score (placeholder - you can enhance this with actual quality metrics)
      const qualityScore = completedPOs > 0 ? 
        Math.min(100, 85 + (onTimePOs / completedPOs) * 15) : 0;

      // Calculate efficiency score
      const efficiencyScore = Math.min(100, autoCompletionPercent * 0.7 + qualityScore * 0.3);

      // Calculate rates
      const completionRate = totalPOs > 0 ? (completedPOs / totalPOs) * 100 : 0;
      const onTimeRate = completedPOs > 0 ? (onTimePOs / completedPOs) * 100 : 0;

      // Calculate automatic rating
      const overallRating = calculateAutoRating(
        completionRate,
        onTimeRate,
        qualityScore,
        totalPOs + totalJobs
      );

      // Calculate category ratings
      const categoryRatings = calculateCategoryRatings({
        completionRate,
        onTimeRate,
        qualityScore,
        totalPOs,
        totalJobs,
        efficiencyScore
      });

      // Monthly performance trend
      const monthlyData = {};
      pos.forEach(po => {
        if (po.createdAt) {
          const date = po.createdAt.toDate ? po.createdAt.toDate() : new Date(po.createdAt);
          const month = date.toISOString().slice(0, 7);
          if (!monthlyData[month]) {
            monthlyData[month] = { orders: 0, spend: 0, completed: 0, onTime: 0 };
          }
          monthlyData[month].orders++;
          monthlyData[month].spend += parseFloat(po.totalAmount) || 0;
          if (po.status === 'completed') {
            monthlyData[month].completed++;
            // Check if on-time
            if (po.deliveryDate && po.completedAt) {
              const deliveryDate = po.deliveryDate.toDate ? po.deliveryDate.toDate() : new Date(po.deliveryDate);
              const completedAt = po.completedAt.toDate ? po.completedAt.toDate() : new Date(po.completedAt);
              if (completedAt <= deliveryDate) monthlyData[month].onTime++;
            }
          }
        }
      });

      const trendData = Object.entries(monthlyData)
        .sort(([a], [b]) => a.localeCompare(b))
        .slice(-6)
        .map(([month, data]) => ({
          month,
          orders: data.orders,
          spend: data.spend,
          completionRate: data.orders > 0 ? (data.completed / data.orders) * 100 : 0,
          onTimeRate: data.completed > 0 ? (data.onTime / data.completed) * 100 : 0
        }));

      // Recent activity
      const activity = [
        ...pos.slice(-5).map(po => ({
          type: 'PO',
          title: `Purchase Order #${po.poNumber || 'N/A'}`,
          status: po.status,
          date: po.createdAt?.toDate ? po.createdAt.toDate() : new Date(po.createdAt),
          amount: po.totalAmount
        })),
        ...jobs.slice(-5).map(job => ({
          type: 'Job',
          title: job.title || 'Job Assignment',
          status: job.status,
          date: job.createdAt?.toDate ? job.createdAt.toDate() : new Date(job.createdAt),
          amount: job.budget
        }))
      ].sort((a, b) => (b.date || 0) - (a.date || 0)).slice(0, 10);

      setPerformanceData({
        totalPOs,
        completedPOs,
        pendingPOs,
        cancelledPOs,
        onTimePOs,
        totalSpend,
        avgOrderValue,
        completionRate,
        onTimeRate,
        totalJobs,
        completedJobs,
        pendingJobs,
        avgJobValue,
        autoCompletionPercent,
        qualityScore,
        efficiencyScore,
        overallRating,
        categoryRatings,
        totalOperations
      });

      setPerformanceTrend(trendData);
      setRecentActivity(activity);

      // Update vendor with automatic rating
      try {
        await updateDoc(doc(db, 'vendors', id), {
          rating: overallRating,
          ratingSource: 'auto_performance',
          performanceMetrics: {
            completionRate,
            onTimeRate,
            qualityScore,
            totalOrders: totalPOs,
            totalSpend,
            lastUpdated: new Date()
          },
          ratingUpdatedAt: new Date()
        });
      } catch (e) {
        console.warn('Failed to update vendor rating:', e);
      }

    } catch (error) {
      console.error('Error fetching vendor performance:', error);
      showError('Failed to load vendor performance data');
    } finally {
      setLoading(false);
    }
  };

  const renderStars = (rating, size = 20) => {
    const stars = [];
    const fullStars = Math.floor(rating);
    const hasHalfStar = rating % 1 >= 0.5;

    for (let i = 1; i <= 5; i++) {
      if (i <= fullStars) {
        stars.push(
          <FiStar
            key={i}
            size={size}
            className="text-yellow-400 fill-current"
          />
        );
      } else if (i === fullStars + 1 && hasHalfStar) {
        stars.push(
          <div key={i} className="relative">
            <FiStar size={size} className="text-gray-300" />
            <FiStar 
              size={size} 
              className="text-yellow-400 fill-current absolute left-0 top-0"
              style={{ clipPath: 'inset(0 50% 0 0)' }}
            />
          </div>
        );
      } else {
        stars.push(
          <FiStar
            key={i}
            size={size}
            className="text-gray-300"
          />
        );
      }
    }
    return <div className="flex">{stars}</div>;
  };

  const getPerformanceColor = (value, threshold = 80) => {
    if (value >= threshold) return 'text-green-600';
    if (value >= threshold * 0.7) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getPerformanceIcon = (value, threshold = 80) => {
    if (value >= threshold) return <FiTrendingUp className="text-green-600" />;
    if (value >= threshold * 0.7) return <FiTrendingUp className="text-yellow-600" />;
    return <FiTrendingDown className="text-red-600" />;
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-indigo-500"></div>
      </div>
    );
  }

  if (!vendor) {
    return (
      <div className="text-center py-8">
        <p className="text-gray-500">Vendor not found</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto space-y-6 px-4 sm:px-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
        <div className="flex items-center space-x-4">
          <button
            onClick={() => navigate('/admin/vendors')}
            className="flex items-center text-gray-600 hover:text-gray-900"
          >
            <FiArrowLeft className="mr-2" size={20} />
            Back to Vendors
          </button>
          <div>
            <h1 className="text-2xl font-bold text-gray-900">{vendor.name} - Performance</h1>
            <p className="text-gray-600">Automatic performance tracking based on work completion</p>
          </div>
        </div>
        
        <div className="flex items-center space-x-3">
          <button
            onClick={fetchVendorPerformance}
            className="flex items-center px-3 py-2 border border-gray-300 rounded-lg hover:bg-gray-50"
          >
            <FiRefreshCw className="mr-2" size={16} />
            Refresh
          </button>
        </div>
      </div>

      {/* Key Performance Metrics */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-6 mb-6">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Overall Rating</p>
              <div className="text-2xl font-bold text-gray-900 mt-1">
                {performanceData.overallRating?.toFixed(1) || '0.0'}
              </div>
              {renderStars(performanceData.overallRating || 0, 20)}
              <p className="text-xs text-gray-500 mt-1">Auto-calculated</p>
            </div>
            <div className="p-3 bg-yellow-100 rounded-full">
              <FiStar className="text-yellow-600" size={24} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Completion Rate</p>
              <div className={`text-2xl font-bold mt-1 ${getPerformanceColor(performanceData.completionRate)}`}>
                {performanceData.completionRate?.toFixed(1) || '0.0'}%
              </div>
              <p className="text-xs text-gray-500 mt-1">
                {performanceData.completedPOs || 0} of {performanceData.totalPOs || 0} POs
              </p>
            </div>
            <div className="p-3 bg-green-100 rounded-full">
              <FiCheckCircle className="text-green-600" size={24} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">On-Time Delivery</p>
              <div className={`text-2xl font-bold mt-1 ${getPerformanceColor(performanceData.onTimeRate)}`}>
                {performanceData.onTimeRate?.toFixed(1) || '0.0'}%
              </div>
              <p className="text-xs text-gray-500 mt-1">
                {performanceData.onTimePOs || 0} on time deliveries
              </p>
            </div>
            <div className="p-3 bg-blue-100 rounded-full">
              <FiClock className="text-blue-600" size={24} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-600">Total Spend</p>
              <div className="text-2xl font-bold text-gray-900 mt-1">
                ₹{performanceData.totalSpend?.toLocaleString() || '0'}
              </div>
              <p className="text-xs text-gray-500 mt-1">
                {performanceData.totalPOs || 0} orders • {performanceData.totalJobs || 0} jobs
              </p>
            </div>
            <div className="p-3 bg-purple-100 rounded-full">
              <FiDollarSign className="text-purple-600" size={24} />
            </div>
          </div>
        </div>
      </div>

      {/* Performance Trends and Activity */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 mb-6">
        {/* Performance Trend Chart */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">Performance Trend</h3>
            <select
              value={selectedTimeframe}
              onChange={(e) => setSelectedTimeframe(e.target.value)}
              className="text-sm border border-gray-300 rounded px-2 py-1 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="3months">Last 3 Months</option>
              <option value="6months">Last 6 Months</option>
              <option value="1year">Last Year</option>
            </select>
          </div>
          
          {performanceTrend.length > 0 ? (
            <div className="space-y-4">
              {performanceTrend.map((data, index) => (
                <div key={data.month} className="flex items-center justify-between p-3 bg-gray-50 rounded">
                  <div>
                    <p className="font-medium text-gray-900">
                      {new Date(data.month + '-01').toLocaleDateString('en-US', { month: 'short', year: 'numeric' })}
                    </p>
                    <p className="text-sm text-gray-500">{data.orders} orders</p>
                  </div>
                  <div className="text-right">
                    <p className="font-medium text-green-600">₹{data.spend.toLocaleString()}</p>
                    <p className="text-sm text-gray-500">{data.completionRate.toFixed(1)}% completion</p>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8 text-gray-500">
              <FiBarChart2 size={32} className="mx-auto mb-2 text-gray-400" />
              <p>No trend data available</p>
            </div>
          )}
        </div>

        {/* Recent Activity */}
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">Recent Activity</h3>
          
          {recentActivity.length > 0 ? (
            <div className="space-y-3">
              {recentActivity.map((activity, index) => (
                <div key={index} className="flex items-center justify-between p-3 border border-gray-200 rounded">
                  <div className="flex items-center space-x-3">
                    <div className={`p-2 rounded-full ${activity.type === 'PO' ? 'bg-blue-100' : 'bg-green-100'}`}>
                      {activity.type === 'PO' ? 
                        <FiFileText className={activity.type === 'PO' ? 'text-blue-600' : 'text-green-600'} size={16} /> :
                        <FiTarget className="text-green-600" size={16} />
                      }
                    </div>
                    <div>
                      <p className="font-medium text-gray-900 break-words">{activity.title}</p>
                      <p className="text-sm text-gray-500">
                        {activity.date?.toLocaleDateString() || 'N/A'}
                      </p>
                    </div>
                  </div>
                  <div className="text-right">
                    <span className={`px-2 py-1 text-xs rounded-full ${
                      activity.status === 'completed' ? 'bg-green-100 text-green-800' :
                      activity.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
                      'bg-gray-100 text-gray-800'
                    }`}>
                      {activity.status}
                    </span>
                    {activity.amount && (
                      <p className="text-sm text-gray-600 mt-1">₹{parseFloat(activity.amount).toLocaleString()}</p>
                    )}
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-8 text-gray-500">
              <FiActivity size={32} className="mx-auto mb-2 text-gray-400" />
              <p>No recent activity</p>
            </div>
          )}
        </div>
      </div>

      {/* Category Performance */}
      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Performance by Category</h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {performanceCategories.map(category => {
            const IconComponent = category.icon;
            const rating = performanceData.categoryRatings?.[category.key] || 0;
            
            return (
              <div key={category.key} className="border border-gray-200 rounded-lg p-4">
                <div className="flex items-center mb-3">
                  <IconComponent className="text-indigo-600 mr-2" size={20} />
                  <h3 className="font-medium text-gray-900">{category.label}</h3>
                </div>
                
                <div className="flex items-center justify-between">
                  {renderStars(rating)}
                  <span className="text-lg font-semibold text-gray-900">
                    {rating.toFixed(1)}
                  </span>
                </div>
                
                {/* Additional metric info */}
                {category.key === 'completion' && (
                  <p className="text-xs text-gray-500 mt-2">
                    {performanceData.completionRate?.toFixed(1)}% completion rate
                  </p>
                )}
                {category.key === 'timeliness' && (
                  <p className="text-xs text-gray-500 mt-2">
                    {performanceData.onTimeRate?.toFixed(1)}% on-time delivery
                  </p>
                )}
                {category.key === 'volume' && (
                  <p className="text-xs text-gray-500 mt-2">
                    {performanceData.totalPOs || 0} POs • {performanceData.totalJobs || 0} jobs
                  </p>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Performance Details */}
      <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">Performance Details</h2>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600">Total Operations</p>
            <p className="text-2xl font-bold text-gray-900">{performanceData.totalOperations || 0}</p>
          </div>
          
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600">Operational Efficiency</p>
            <p className="text-2xl font-bold text-green-600">
              {performanceData.efficiencyScore?.toFixed(1) || '0.0'}%
            </p>
          </div>
          
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600">Quality Score</p>
            <p className="text-2xl font-bold text-blue-600">
              {performanceData.qualityScore?.toFixed(1) || '0.0'}%
            </p>
          </div>
          
          <div className="text-center p-4 bg-gray-50 rounded-lg">
            <p className="text-sm text-gray-600">Avg Job Value</p>
            <p className="text-2xl font-bold text-purple-600">
              ₹{performanceData.avgJobValue?.toLocaleString() || '0'}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}